"""Direct client for the persistent FT2 MCP bridge socket (faster than spawning ft2 CLI each time)."""
import socket, json

SOCKET = "/tmp/keygen-ft2.sock"
LIMIT = 240 * 1024

def _exchange(message):
    raw = json.dumps(message).encode() + b"\n"
    with socket.socket(socket.AF_UNIX) as sock:
        sock.settimeout(600)
        sock.connect(SOCKET)
        sock.sendall(raw)
        with sock.makefile("rb") as reader:
            result = reader.readline(LIMIT + 1)
    reply = json.loads(result)
    if "error" in reply:
        raise RuntimeError(reply["error"])
    return reply["result"]

def call(name, arguments=None):
    arguments = arguments or {}
    reply = _exchange({"op": "call", "name": name, "arguments": arguments})
    if reply.get("isError"):
        raise RuntimeError(json.dumps(reply))
    # extract text
    texts = [c.get("text","") for c in reply.get("content",[]) if c.get("type")=="text"]
    text = "\n".join(texts)
    try:
        return json.loads(text)
    except Exception:
        return text

def list_tools():
    return _exchange({"op": "list"})

if __name__ == "__main__":
    import time
    t0=time.time()
    for i in range(20):
        call("module_info", {})
    print("20 calls took", time.time()-t0, "s")
EOF
